import{_ as n,o as i,c as t,a3 as a}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Bauen, prüfen und veröffentlichen","description":"ATLAS-Pluginpakete und Repository-Kataloge vorbereiten und prüfen.","frontmatter":{"title":"Bauen, prüfen und veröffentlichen","description":"ATLAS-Pluginpakete und Repository-Kataloge vorbereiten und prüfen."},"headers":[],"relativePath":"projects/atlas-plugins/developers/publishing.md","filePath":"projects/atlas-plugins/developers/publishing.md","lastUpdated":1792849697000}'),s={name:"projects/atlas-plugins/developers/publishing.md"};function r(l,e,o,d,u,h){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="bauen-prufen-und-veroffentlichen" tabindex="-1">Bauen, prüfen und veröffentlichen <a class="header-anchor" href="#bauen-prufen-und-veroffentlichen" aria-label="Permalink to &quot;Bauen, prüfen und veröffentlichen&quot;">​</a></h1><p>Die <a href="./../plugin-template">Plugin-Vorlage</a> automatisiert die wiederholbaren Schritte für ein eigenes GitHub-Repository.</p><h2 id="paket-und-katalog-bauen" tabindex="-1">Paket und Katalog bauen <a class="header-anchor" href="#paket-und-katalog-bauen" aria-label="Permalink to &quot;Paket und Katalog bauen&quot;">​</a></h2><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Der Build erzeugt aus dem Manifest das installierbare Paket und synchronisiert den passenden Plugin-Eintrag im <code>repository.json</code>. Die Prüfung kontrolliert unter anderem IDs, Paketpfad und die Metadaten im erzeugten Paket. Ein GitHub-Actions-Workflow führt Build und Prüfung bei Pushes und Pull Requests aus.</p><h2 id="veroffentlichungsschritte" tabindex="-1">Veröffentlichungsschritte <a class="header-anchor" href="#veroffentlichungsschritte" aria-label="Permalink to &quot;Veröffentlichungsschritte&quot;">​</a></h2><p>Beachte die <a href="./compatibility">Versions- und Kompatibilitätsregeln</a> einschließlich Sicherung, Migrationsgrenzen und Wiederherstellung.</p><ol><li>Erhöhe <code>version</code> im Manifest bei jeder funktionalen oder sichtbaren Veröffentlichung.</li><li>Führe <code>npm run build</code> und <code>npm run check</code> aus.</li><li>Prüfe, ob Manifest, Katalog und erzeugtes Paket dieselbe ID und Version enthalten.</li><li>Kontrolliere Paketdateien, Asset-Pfade, externe Anfragen und deklarierte Fähigkeiten.</li><li>Veröffentliche den Katalog durch Push nach <code>main</code>: <code>https://raw.githubusercontent.com/&lt;owner&gt;/&lt;repo&gt;/main/repository.json</code>. GitHub Pages ist dafür nicht nötig; es dient optional zur Veröffentlichung der <code>install.html</code>.</li><li>Füge die Katalog-URL in ATLAS Administration hinzu und teste Vorschau und Paketinstallation.</li></ol><p>Halte die Plugin-ID nach der ersten Veröffentlichung stabil. Größere Binärdateien gehören nicht in das textbasierte Paketformat; hoste sie separat und referenziere sie über eine URL.</p><h2 id="installationsstatus" tabindex="-1">Installationsstatus <a class="header-anchor" href="#installationsstatus" aria-label="Permalink to &quot;Installationsstatus&quot;">​</a></h2><p>Der App-Server installiert geprüfte Repository- und Importpakete im persistenten Plugin-Verzeichnis und stellt statische Webdateien unter <code>/plugin-assets/&lt;slug&gt;/</code> bereit. Beim Öffnen läuft deren JavaScript im Browser; beliebige Node-Module oder Runtime-Hooks werden nicht automatisch registriert. Die Installation ist keine Sandbox: Prüfe Paket und Browsercode vor dem Öffnen. Ein Paketbuild allein ersetzt keine Laufzeit- oder Sicherheitsprüfung.</p>`,11)])])}const f=n(s,[["render",r]]);export{c as __pageData,f as default};
